window.MONSTER_CHUNK_150 = [{"name":"Crysolax","cr":15,"xp":51200,"alignment":"LE","size":"Huge","type":"outsider","subtypes":["earth","elemental","extraplanar"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["scintillating aura (20 ft.; DC 20 Will)"],"ac":27,"ac_touch":11,"ac_flat_footed":24,"ac_mods":"+3 Dex, +16 natural, -2 size","hp":172,"hd":"15d10+90","hdvalue":15,"fort":17,"ref":12,"will":7,"dr":"10/magic and bludgeoning","immunities":["blindness","light-based effects"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":26,"weaknesses":["vulnerable to sonic"],"speed":[{"type":"land","speed":50}],"melee":"2 claws +22 (1d8+8/19-20 plus grab), bite +21 (2d6+8 plus 1d6 Dex damage)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"petrifying bite"},{"type":"scintillating aura"}],"strength":27,"dexterity":16,"constitution":22,"intelligence":12,"wisdom":14,"charisma":16,"baseatk":15,"cmb":25,"cmb_special":"+4 vs. grapple","cmd":38,"cmd_special":"+12 vs. trip","feats":[{"feat":"Ability Focus (petrifying bite)"},{"feat":"Alertness"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Weapon Focus (claw)"},{"feat":"Great Fortitude"},{"feat":"Vital Strike"}],"skills":[{"skill":"Acrobatics","value":21},{"skill":"Climb","value":26},{"skill":"Escape Artist","value":21},{"skill":"Knowledge (planes)","value":19},{"skill":"Perception","value":24},{"skill":"Sense Motive","value":4},{"skill":"Stealth","value":13},{"skill":"Survival","value":20}],"languages":["Common","Terran"],"environments":["any (Plane of Earth)"],"organizations":["solitary","carat (2-4)"],"treasure":"incidental coins and items; twice standard gemstones","description_visual":"This creature looks like a horrible amalgam of a centipede and a praying mantis made out of translucent white crystal with brilliant multifaceted blue eyes.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Petrifying Bite","kind":"Ex","details":"The bite of a crysolax deals 1d6 points of Dexterity damage. A creature reduced to Dex 0 is turned to crystal (as the stone to flesh spell) permanently if it fails a DC 25 Fortitude save. The save DC is Constitution-based and includes a +2 bonus from the crysolax's Ability Focus feat."},{"type":"Scintillating Aura","kind":"Ex","details":"As long as there is a light source present within 30 ft. of it, the crysolax constantly radiates an aura that duplicates the effects of a rainbow pattern spell (CL 15th). The save is Charisma-based."}],"description":"A terrifying predator native to the Plane of Earth (and also a pocket dimension known as the Demiplane of Crystal), the crysolax is a hunter, active most often during the daylight hours. During the day, natural sunlight refracts from the crysolax causing it to appear to be a multitude of different colors. It uses this natural sunlight to activate its aura when hunting or in combat.\n\nA crysolax spends its days hunting creatures native to the Plane of Earth, while at night, the creature is usually found in its lair, a large and complex maze of twisting corridors, caverns, and spiraling tunnels located deep within the rocky earth of its native plane. A crysolax lair usually consists of 2-4 adults and twice that number in smaller noncombatant crysolax. The female lays 4-8 large crystal eggs usually once per year. These eggs usually hatch within 60 days and a crysolax reaches maturity within two years. Its lair is also scattered with any treasure it may have gathered. Though not a creature known for collecting treasure, a crysolax is quite fond of gemstones, and as such a large amount of said treasure usually can be found in its lair. While a crysolax has no need to eat, some do enjoy ingesting certain gemstone (the exact type seems to vary between each crysolax).\n\nA crysolax attacks with its bite, attempting to petrify the strongest opponents first. It also rakes and slashes with its razor-sharp claws or grabs a foe and repeatedly subjects it to its bite attack, knowing that eventually the victim will succumb to its petrifying nature.","ecology":"","habitat_society":""},{"name":"Empyreal","cr":15,"xp":51200,"alignment":"LG","size":"Large","type":"outsider","subtypes":["angel","extraplanar","good","lawful"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect evil"},{"type":"low-light vision"}],"auras":["aura of goodness","protective aura"],"ac":27,"ac_touch":13,"ac_flat_footed":23,"ac_mods":"+4 Dex, +14 natural, -1 size | +4 deflection vs. evil","hp":136,"hd":"13d10+65","hdvalue":13,"fort":15,"ref":12,"will":8,"save_mods":"+4 vs. poison, +4 vs. evil","dr":"10/evil","immunities":["acid","cold","petrification","death effects"],"resists":[{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":26,"speed":[{"type":"land","speed":40},{"type":"fly","speed":70,"maneuverability":"good"}],"melee":"+3 flaming longsword +23 (1d8+10 plus 1d6 fire)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"radiant blast"}],"spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect evil"}]},{"frequency":"at-will","spells":[{"spell":"aid"},{"spell":"continual flame"},{"spell":"discern lies"},{"spell":"dispel magic"},{"spell":"holy smite"},{"spell":"invisibility","details":"self only"},{"spell":"plane shift"},{"spell":"remove curse"},{"spell":"remove disease"},{"spell":"remove fear"}]},{"frequency":"1/day","spells":[{"spell":"heal"},{"spell":"raise dead"}]},{"frequency":"3/day","spells":[{"spell":"blade barrier"},{"spell":"cure serious wounds"},{"spell":"flame strike"},{"spell":"scorching ray","details":"3 rays"}]},{"frequency":"5/day","spells":[{"spell":"cure moderate wounds"}]}],"strength":24,"dexterity":18,"constitution":20,"intelligence":18,"wisdom":18,"charisma":20,"baseatk":13,"cmb":21,"cmd":35,"feats":[{"feat":"Alertness"},{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Weapon Focus (longsword)"}],"skills":[{"skill":"Diplomacy","value":21},{"skill":"Fly","value":22},{"skill":"Heal","value":20},{"skill":"Intimidate","value":18},{"skill":"Knowledge (planes)","value":20},{"skill":"Knowledge (religion)","value":17},{"skill":"Perception","value":28},{"skill":"Sense Motive","value":24},{"skill":"Stealth","value":16},{"skill":"Survival","value":20}],"languages":["Celestial","Common","Draconic","Infernal","truespeech"],"environments":["any good-aligned plane"],"organizations":["solitary","group (2-4)"],"treasure":"double standard","description_visual":"This creature resembles a man-sized column of white fire. Within the burning fires seems to be a winged humanoid-shaped creature dressed in shining armor.","group":"Angel","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Aura of Goodness","kind":"Su","details":"An empyreal radiates an aura in a 30-foot radius spread around its form. Any non-evil creature in this area must succeed on a DC 23 Will save or be overcome with awe and unable to attack the empyreal that round. Evil creatures within the area must make a successful DC 23 Will save or be unable to even look at that empyreal for one day. An affected evil creature functions as if blinded (as the blindness spell) when attacking that empyreal. On a successful save, a creature is immune to the aura of goodness of that empyreal for one day. The save DC is Charisma-based and includes a +2 bonus."},{"type":"Radiant Blast","kind":"Su","details":"Once per day, an empyreal can increase the radiance of its form and release it in a cone-shaped blast to a range of 60 ft. that deals 15d6 points of damage and blinds any creature in the area (as the blindness spell) for 3d6 minutes. Affected creatures can make a successful DC 21 Reflex save to halve the damage and avoid being blinded. The save DC is Constitution-based."}],"description":"Empyreals are knights and warriors in the service of good deities. While closely associated with other angels, empyreals are often found leading holy armies against the forces of evil. They are fiery, quick-tempered, and forceful, but always fair.\n\nIn the upper planes those that serve as commanders spend their time organizing their troops and planning strategies. While the more powerful empyreals serve as commanders, the lesser can be found performing any number of duties, whether it is acting as guard, servant, or messenger.\n\nEmpyreals that enter combat prefer to attack their opponents with a mixture of magic and direct physical attacks with their longswords. Against powerful foes, an empyreal uses its radiant blast to catch as many foes as it can in the area of effect. During battle, an empyreal often stays aloft where it can blast its foes with spells while staying out of melee range.","ecology":"","habitat_society":"","gear":"+3 flaming longsword"},{"name":"Fisherman","cr":15,"xp":51200,"alignment":"LE","size":"Large","type":"outsider","subtypes":["aquatic","evil","lawful","native"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"deathwatch","modifier":"15 miles"},{"type":"weather sense","modifier":"30 miles"}],"ac":21,"ac_touch":11,"ac_flat_footed":19,"ac_mods":"+2 Dex, +10 natural, -1 size","hp":202,"hd":"15d10+120","hdvalue":15,"fort":13,"ref":11,"will":16,"dr":"15/magic","immunities":["cold"],"resists":[{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":26,"speed":[{"type":"land","speed":40},{"type":"swim","speed":30}],"melee":"+3 boat hook +26 (1d8+13) or +3 boat hook +22 (1d8+9), +3 boat hook +22 (1d6+9) or +3 boat hook +22 (1d8+9), +3 gaff hook +22 (1d8+9)","ranged":"net +16 (entangle)","space":"10 ft.","reach":"10 ft.","spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":23,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"deathwatch","details":"15 mile radius"},{"spell":"freedom of movement","details":"underwater"}]},{"frequency":"1/day","spells":[{"spell":"summon nature's ally V"}]}],"spellsprepared_caster_level":9,"spellsprepared_concentration":17,"spellsprepared":[{"spell_level":5,"spell_slots":1,"spells":[{"spell":"slay living","count":2}]},{"spell_level":4,"spell_slots":1,"spells":[{"spell":"control water"},{"spell":"spell immunity"},{"spell":"unholy blight"}]},{"spell_level":3,"spell_slots":1,"spells":[{"spell":"bestow curse"},{"spell":"deeper darkness"},{"spell":"magic circle against good"},{"spell":"water walk"}]},{"spell_level":2,"spell_slots":1,"spells":[{"spell":"align weapon"},{"spell":"darkness"},{"spell":"death knell"},{"spell":"enthrall"},{"spell":"silence"}]},{"spell_level":1,"spell_slots":1,"spells":[{"spell":"bane"},{"spell":"command"},{"spell":"curse water","count":2},{"spell":"obscuring mist"},{"spell":"sanctuary"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"create water"},{"spell":"detect magic"},{"spell":"mending"}]}],"strength":28,"dexterity":15,"constitution":26,"intelligence":15,"wisdom":21,"charisma":20,"baseatk":15,"cmb":25,"cmd":37,"feats":[{"feat":"Cleave"},{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Great Cleave"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Two-Weapon Fighting"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":23},{"skill":"Craft (any)","value":20},{"skill":"Diplomacy","value":23},{"skill":"Intimidate","value":23},{"skill":"Knowledge (local)","value":20},{"skill":"Perception","value":23},{"skill":"Sense Motive","value":23},{"skill":"Swim","value":35}],"languages":["Aquan","Sylvan"],"sq":[{"type":"amphibious"},{"type":"create soul cage"},{"type":"exotic weapons"},{"type":"gambling"}],"environments":["any aquatic"],"organizations":["solitary"],"treasure":"standard (+3 boat hook, +3 gaff hook, net)","description_visual":"This large humanoid stands over 10 ft. tall, and is clad in the garb of a mundane fisherman. Its eyes glow with an eerie blue light and its grizzled face is trimmed with a gnarled beard from which scuttle small crabs, fish, and shrimp.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Create Soul Cage","kind":"Su","details":"Using debris that floats to the bottom of the ocean, a fisherman can construct a soul cage. The soul cage is a magical construction that, through its crafting, has been endowed with a trap the soul spell. The spell requires no material components other than the debris from which it is created. The magic of the soul cage only functions for fishermen and the souls remain trapped for as long as the fisherman wishes and remains on the Material Plane. Usually, only upon the death of the fisherman may the trapped souls be released. A soul cage can hold up to six souls at any given time."},{"type":"Deathwatch","kind":"Sp","details":"A fisherman makes constant use of the spell deathwatch, as cast by a 15th level cleric. The range of a fisherman's deathwatch is 1 mile per hit die, allowing it to sense the life state of any creature within its territory. This ability can be negated, but the fisherman can reactivate it the next round as a free action."},{"type":"Exotic Weapons","kind":"Ex","details":"A fisherman is proficient in the use of the boat hook and gaff hook."},{"type":"Gambling","kind":"Ex","details":"Fishermen are fond of games and gambling and should one be offered a fair chance of odds, he may find a wager impossible to resist. In this way, it may be possible to bargain for the release of the soul of a companion or loved one. Although evil, fishermen are bound by a personal code and honor the terms of a wager if they lose. Spells Fishermen cast divine spells as 9th-level clerics. They don't gain access to domains or other cleric abilities."},{"type":"Weather Sense","kind":"Su","details":"A fisherman always knows the condition of the weather within a 30 mile radius, even if he is currently underwater."}],"description":"The fisherman is a rare creature not often encountered by the mortals of the material world. Sages and scholars often postulate these\n\nboathooks, gaff hooks, and nets to ensnare and slay those who intrude upon their habitat. All fishermen seem to be male - no female of the species has ever been witnessed by any sailor. They are powerful creatures who enjoy tormenting seafarers and work hard to collect the souls of those who die at the hands of the sea. At the bottom of the ocean they may be found tending to devices called soul cages that resemble ordinary lobster traps, though they are used to imprison the spirits of the drowned. The territory of a fisherman can extend over a dozen miles from its lair.\n\nFishermen stand between 11 and 12 ft. tall and weigh 1,600 pounds.\n\nWhen a fisherman detects a great storm at sea, or is otherwise aware that sailors are meeting watery deaths, it rises to the surface in order to start collecting as many of the souls as it can. An individual fisherman may tend to as many as 3d6 soul cages, each containing the incarcerated spirits of 1d6 unfortunate sailors, all of which have met their deaths through storm, shipwreck, or some other maritime disaster. Those slain by intentional violence are left to wander the depths by the fisherman. They are very competitive with others of their kind but occasionally they swap souls to enhance their own collections.\n\nSpecial Weapons\n\nBoat Hook: A boat hook resembles a quarterstaff with a barbed hook at one end. Sailors use boat hooks to snag mooring lines and pull in small boats. Because a boat hook isn't intended to be used as a weapon, it requires the Exotic Weapon Proficiency to be used in that capacity. A boat hook is a double weapon. The damage is given as hook/staff.\n\nCost 6 gp; Small 1d4/1d3, Medium 1d6/1d4, Large 1d8/1d6; Critical x2; Weight 5 lb.; Type Bludgeoning/Piercing.\n\nGaff Hook: A gaff hook is a curved metallic hook with a cross bar. Gaff hooks are used by fishermen to lift heavy catches into their boats. Because a gaff hook isn't intended to be used as a weapon, it requires the Exotic Weapon Proficiency to be used in that capacity.\n\nCost 4 gp; Small 1d4, Medium 1d6, Large 1d8; Critical x2; Weight 3 lb.; Type Piercing.\n\naquatic spirits may hail from some other plane of existence, whilst others assume the fisherman is some strange form of undead, the powerful soul of a legendary seaman fated to lurk in the depths of the ocean. Sailors know only that they are to be feared. Although they don't often engage in melee combat, many have found to their own detriment that fishermen are quite skilled. Fighting with a variety of maritime tools and weapons, fishermen favor.","ecology":"","habitat_society":""},{"name":"Herald Of Tsathogga","cr":15,"xp":51200,"alignment":"CE","size":"Huge","type":"aberration","subtypes":["chaotic","evil","extraplanar"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":27,"ac_touch":11,"ac_flat_footed":24,"ac_mods":"+3 Dex, +16 natural, -2 size","hp":231,"hd":"22d8+132","hdvalue":22,"hp_mods":["regeneration 10 (good, fire)"],"fort":12,"ref":12,"will":18,"dr":"10/good","resists":[{"type":"sonic","value":15}],"weaknesses":["bloated"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"bite +21 (2d6+7 plus grab), 10 tentacles +20 (1d8+3  plus paralysis), tongue +20 (1d6+3 plus grab)","space":"15 ft.","reach":"10 ft. (30 ft. with tongue)","special_attacks":[{"type":"bellow"},{"type":"paralysis","details":"1d6+4 rounds, DC 26"},{"type":"swallow whole","details":"2d6+7 plus 2d6 acid damage, AC 18, 23 hp"}],"strength":24,"dexterity":16,"constitution":20,"intelligence":7,"wisdom":16,"charisma":12,"baseatk":16,"cmb":25,"cmb_special":"+4 vs. grapple","cmd":38,"feats":[{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Stealth)"},{"feat":"Toughness"},{"feat":"Weapon Focus (tentacle)"},{"feat":"Weapon Focus (tongue)"}],"skills":[{"skill":"Intimidate","value":14},{"skill":"Perception","value":34},{"skill":"Stealth","value":15},{"skill":"Swim","value":19}],"environments":["warm marshes"],"organizations":["solitary"],"treasure":"standard","description_visual":"This creature appears to be a gigantic pale yellow-green frog with oversized monstrous eyes. In place of its legs and forelimbs are many long, writhing tentacles it uses to pull itself along the ground.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Bellow","kind":"Su","details":"A herald of Tsathogga has two distinct bellows, each usable once every 1d4 rounds. The first is a trilling croak like that of a frog. All opponents with 30 ft. hearing this trilling must succeed on a DC 22 Fortitude save or be deafened for 1d6+4 rounds. Opponents within 10 ft. must make a DC 22 Fortitude save or be stunned for 1d4 rounds. Alternately, a herald can focus its bellow attack against a single opponent within 100 ft. The opponent takes 5d6 points of sonic damage. A successful DC 22 Reflex save reduces the damage by half. The save DCs are Charisma-based."},{"type":"Bloated","kind":"Ex","details":"Because of its bloated, heavy body, a herald of Tsathogga that attacks with more than 5 tentacles in one round cannot move that round."},{"type":"Regeneration","kind":"Ex","details":"A herald of Tsathogga takes normal damage from fire and good-aligned weapons, and from spells or effects with the good descriptor."}],"description":"The dark, dismal tropical swamps and fens of the world are home to a horrible creature known only as the herald of Tsathogga. A vaguely froglike thing almost 20 ft. across, the herald of Tsathogga is a nightmare creature that is spoken of only in hushed whispers. The creature is believed to have been created by the Frog God as punishment against humanity for wrongdoings done to Tsathogga and his worshippers.\n\nIts warty, putrid skin is a pale yellow-green, and two monstrous eyes that have seen unknown secrets gaze from its fleshy face. The body of the thing resembles that of a massive toad, but rather than legs the herald of Tsathogga drags itself through the murky terrain on ten thick tentacles.\n\nThese tentacles are covered in tiny lancets that inject paralytic venom.\n\nSome who have seen the herald of Tsathogga swear that it is capable of flight, but these reports are dismissed as madman's fantasy.\n\nThough only one herald is thought to exist, rumors as of late, speak of at least three of these creatures in existence.\n\nA herald of Tsathogga attacks first with its tentacles, attempting to paralyze or otherwise incapacitate as many opponents as possible.\n\nParalyzed opponents are pulled to the creature's maw and bitten. Its tentacles are not coordinated enough to grab moving targets, so it cannot pick up opponents that have not been paralyzed.","ecology":"","habitat_society":""},{"name":"Pelagos Sea Spider","cr":15,"xp":51200,"alignment":"N","size":"Huge","type":"magical beast","subtypes":["aquatic"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"watersense","modifier":"60 ft."}],"ac":28,"ac_touch":12,"ac_flat_footed":25,"ac_mods":"+4 Dex, +16 natural, -2 size","hp":230,"hd":"20d10+120","hdvalue":20,"fort":20,"ref":16,"will":12,"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"speed":[{"type":"swim","speed":90}],"melee":"bite +26 (2d8+7 plus poison plus grab), 4  slams +25 (2d6+7)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"swallow whole","details":"2d6+7 plus 1d8 acid damage, AC 18, 23 hp"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":26,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"stinking cloud"}]},{"frequency":"3/day","spells":[{"spell":"cone of cold"},{"spell":"lightning bolt","details":"affects a 30-ft. radius around the pelagos rather than a single target"}]}],"strength":25,"dexterity":16,"constitution":22,"intelligence":20,"wisdom":18,"charisma":18,"baseatk":20,"cmb":29,"cmb_special":"+4 vs. grapple","cmd":43,"cmd_special":"+12 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Fast Swim"},{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Swim-by Attack"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Diplomacy","value":24},{"skill":"Escape Artist","value":24},{"skill":"Knowledge (nature)","value":25},{"skill":"Knowledge (religion)","value":25},{"skill":"Perception","value":31},{"skill":"Sense Motive","value":28},{"skill":"Stealth","value":17,"special":"+25 when floating on the surface"},{"skill":"Swim","value":20}],"languages":["Aquan","Common","Draconic","Elven","Sylvan"],"environments":["any aquatic"],"organizations":["solitary"],"treasure":"standard","description_visual":"This creature resembles similar arachnids found on land. Its color ranges through various shades of blue and green with distinct black markings. Its legs and bodies are covered with thousands of fine, sticky hairs.","group":"Sea Spider","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 26; frequency 1/round for 4 rounds; effect 1d3 Con damage; cure 2 consecutive saves. A creature that dies from this poison turns into water and flows away (and is irrevocably dead save for a miracle, wish, or the intervention of a deity). The save DC is Constitution-based."},{"type":"Watersense","kind":"Ex","details":"A pelagos can pinpoint the location of anything within 60 ft. that is touching the water."}],"description":"This great sea spider makes its home in the deep ocean never venturing close to the coast or shorelines. Its lair is often made in sunken ships or underwater caverns and caves. It sustains itself on a steady diet of fish and aquatic plants.\n\nA pelagos is thought to be the creation of an ancient sea god set upon the world to either guard or harass ships and waterborne travelers. Many cultures revere the great pelagoses as sea gods themselves and often make sacrifices to them to ensure a safe ocean journey (or to bring about a curse upon the heads of pirates, buccaneers, or other water bandits who have wronged the community).","ecology":"","habitat_society":""},{"name":"Petrified Horror","cr":15,"xp":51200,"alignment":"N","size":"Medium","type":"construct","init":8,"senses":[{"type":"blindsight","modifier":"60 ft."}],"auras":["frightful presence (60 ft., DC 20)"],"ac":24,"ac_touch":14,"ac_flat_footed":20,"ac_mods":"+4 Dex, +10 natural","hp":140,"hd":"20d10+30","hdvalue":20,"fort":6,"ref":10,"will":6,"dr":"5/adamantine","immunities":["construct traits (+30 hp)","magic"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +25 (2d6+5)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bloodstorm"}],"strength":21,"dexterity":19,"wisdom":11,"charisma":10,"baseatk":20,"cmb":25,"cmd":39,"feats":[{"feat":"Improved Initiative","type":"bonus"}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"A revolting stack of carnage stands before you. Its delicate silhouette belies the true horror that it is. It is as if someone carved a human-sized sculpture from the still-living flesh, bone and muscle of a much-larger creature, and then somehow gave that figure life.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Bloodstorm","kind":"Su","details":"A petrified horror can create a bloodstorm effect (as the spell) centered upon itself as a free action once every 2 minutes. The bloodstorm forms a whirlwind of blood in a column 25 ft. in diameter and 40 ft. high. The effect has a duration of 12 rounds, requiring those within to make a DC 20 Reflex save to avoid being blinded while they remain within the whirlwind and for 2d6 rounds after leaving it and a DC 20 Will save to avoid becoming panicked if less than 8 HD or frightened if 8 HD or above for the duration of the effect. Furthermore, creatures fighting within the bloodstorm or ranged attacks passing through it take -4 penalty on attack rolls Finally, the blood is slightly acidic and deals 1d4 points of acid damage per round. The petrified horror is immune to the effects of the bloodstorm, including the attack penalties, and the whirlwind remains centered on the petrified horror even if it moves. The save DCs are Constitution-based. Full details of the bloodstorm spell can be found in Relics & Rituals by Sword & Sorcery Studios."}],"description":"The name of the petrified horror belies the true nature of this hideous construct. For while it is true that the construct is crafted from the petrified remains of a Large creature, it isn't until the new Medium statue is returned to flesh from its prison of stone that the horror is unleashed. Until then it just resembles an ordinary statue in whatever shape it was sculpted to be and is incapable of action.\n\nThis can be quite disconcerting when a delicate ballerina statue suddenly becomes a lumbering pile of bleeding meat and bone. Creators of these creatures often use them like time bombs, inert until freed by the spells of an inquisitive intruder or as part of a trap activated by the intruders. They instinctively recognize and avoid harming their creator but have no compunctions about destroying anything and anyone else they see.\n\nIn statue form, a typical specimen stands 5 to 8 ft. tall and, being composed of solid stone, weighs anywhere from 1,000 to 1,800 pounds. Despite being a typical statue, it does give off a moderate aura of transmutation. When the creator or someone else casts stone to flesh or break enchantment the construct transforms to flesh and weighs 300 to 500 pounds depending on its height. As a construct it is doesn't require a Fortitude save to survive the transformation. Because the petrified horror is constructed from a larger creature, it gains the bonus hit points of a size Large construct rather than a Medium. Because it has no actual eyes, it sees through blindsight rather than with the traditional darkvision and low-light vision of a construct.\n\nDespite its lumbering appearance, a petrified horror's newly crafted form is quite quick and agile. It moves with a discernable squishing noise and leaves a trail of blood and ichor wherever it goes.\n\nPetrified horrors are incapable of speech and don't understand or heed commands.\n\nPetrified horrors are typically left in out-of-the-way places by their creators, so when activated the damages they cause can be minimized. Once released from its stony imprisonment petrified horrors immediately go into a rampage destroying all they see, preferring living creatures over inanimate objects but content to demolish even inanimate objects if that is all there is. As part of their programming, they rush directly into the center of whatever group is nearest to them (bull rushing if necessary) while flailing with their fists. Once they are in amongst their foes, they use their bloodstorm ability as they continue to fight.\n\nConstruction\n\nA petrified horror is carved from the petrified form of a Large creature which usually costs 10,000 gp to procure. Special masterwork tools for this process worth 500 gp are also required and are ruined in the creation process. Sculpting the body from the base material requires a DC 25 Craft (sculptures) check. Failure means that the petrified creature's form has been cracked and ruined and a new Large petrified creature must be procured.\n\nPETRIFIED HORROR\n\nCL 14th; Price 110,000 gp\n\nCONSTRUCTION\n\nRequirements Craft Construct, animate dead, bloodstorm, flesh to stone, geas/quest, limited wish, caster must be at least 14th level; Skill Craft (sculptures) DC 25; Cost 65,500 gp.","ecology":"","habitat_society":"","credit":"Original author Greg A. Vaughan  Originally appearing in Slumbering Tsar (© Frog God Games/ Greg A. Vaughan, 2012)"},{"name":"Shaggy Demodand","cr":15,"xp":51200,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","demodand","evil","extraplanar"],"init":7,"senses":[{"type":"darkvision","modifier":"120 ft."}],"ac":29,"ac_touch":13,"ac_flat_footed":26,"ac_mods":"+3 Dex, +16 natural","hp":157,"hd":"15d10+75","hdvalue":15,"fort":14,"ref":10,"will":18,"dr":"15/good and magic","immunities":["acid","poison","mind-affecting effects"],"resists":[{"type":"cold","value":10},{"type":"fire","value":10}],"sr":26,"speed":[{"type":"land","speed":40},{"type":"fly","speed":50,"maneuverability":"average"}],"melee":"2 claws +24 (1d6+9), bite +24 (2d6+9) or morningstar +24 (1d8+9), bite +24 (2d6+9)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":20,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect good"},{"spell":"detect magic"},{"spell":"detect thoughts"},{"spell":"fear"},{"spell":"gaseous form"},{"spell":"invisibility","details":"self only"},{"spell":"magic circle against good"},{"spell":"see invisibility"},{"spell":"tongues"}]},{"frequency":"1/day","spells":[{"spell":"chaos hammer"},{"spell":"mass charm monster"},{"spell":"summon","details":"level 6, 1d6 tarry demodands or 1d4 slime demodands 60%; or 1d2 shaggy demodands 30%"}]},{"frequency":"3/day","spells":[{"spell":"cloudkill"},{"spell":"dispel magic"},{"spell":"fog cloud"},{"spell":"ray of enfeeblement"},{"spell":"stinking cloud"}]}],"strength":28,"dexterity":16,"constitution":21,"intelligence":18,"wisdom":18,"charisma":20,"baseatk":15,"cmb":34,"cmd":51,"feats":[{"feat":"Alertness"},{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Improved Bull Rush"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"}],"skills":[{"skill":"Acrobatics","value":14},{"skill":"Bluff","value":23},{"skill":"Diplomacy","value":23},{"skill":"Fly","value":13},{"skill":"Intimidate","value":23},{"skill":"Knowledge (arcana)","value":19},{"skill":"Knowledge (planes)","value":22},{"skill":"Perception","value":34},{"skill":"Sense Motive","value":6},{"skill":"Spellcraft","value":19},{"skill":"Stealth","value":21},{"skill":"Survival","value":21}],"languages":["Abyssal","Common","Ignan","Infernal","Terran"],"environments":["any (Tarterus)"],"organizations":["solitary","troupe (2-5)"],"treasure":"standard","description_visual":"This creature resembles a man-sized, bipedal, frog-like creature with crimson skin. It is bloated and its skin hangs in great folds about its body. Its eyes are slit-pupiled and black, and its head sports a large, wide, frog-like mouth. Large bat-like wings protrude from its shoulders.","group":"Demodand","source":"Tome of Horrors Complete (3pp)","description":"The mighty shaggy demodands are the ruling class of the demodand race. No greater demodands are known to exist, though rumors lately hint at a single, powerful demodand of near-deity status. Shaggy demodands are by far the most malign, selfish, evil, and ruthless of the tripartite race of demodands. They are the nobility and upper class of demodand society and commanders of the demodand armies. A typical shaggy demodand stands 6 ft. tall and weighs about 550 pounds. Shaggy demodands usually attack with their powerful claws and bite, though they sometimes employ weapons (morningstars or bastard swords).","ecology":"","habitat_society":"","credit":"The Shaggy Demodand originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission.","gear":"morningstar"},{"name":"Sojourner Of The Sea","cr":15,"xp":51200,"alignment":"N","size":"Medium","type":"construct","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":30,"ac_touch":10,"ac_flat_footed":30,"ac_mods":"+20 natural","hp":150,"hd":"20d10+40","hdvalue":20,"fort":6,"ref":6,"will":6,"dr":"20/-","immunities":["construct traits (+40 hp)","magic"],"speed":[{"type":"land","speed":20},{"type":"burrow","speed":20},{"type":"climb","speed":20}],"melee":"2 slams +28 (2d8+12/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"aquatic combat"},{"type":"aquatic entangle"}],"strength":27,"dexterity":11,"wisdom":11,"charisma":10,"baseatk":20,"cmb":28,"cmd":38,"skills":[{"skill":"Climb","value":16}],"sq":[{"type":"resilient"}],"environments":["any oceans"],"organizations":["solitary"],"treasure":"none","description_visual":"This metallic construct appears as a crudely rendered statue of a human male, with fully articulated joints. Though its facial features are nothing more than vague shapes with little definition, its torso is carved with an intricate pattern of runes. Along the area of its left \"thigh\" is a long silvery abrasion, perhaps the result of some ancient battle.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Aquatic Combat","kind":"Ex","details":"A sojourner suffers no penalties when fighting underwater."},{"type":"Aquatic Entangle","kind":"Su","details":"Once every four rounds, a sojourner can animate the local sea flora to entrap its opponents. This ability functions as an entangle spell (Reflex DC 20 partial; CL 20th)."},{"type":"Immunity to Magic","kind":"Ex","details":"A sojourner is immune to spells or spell-like abilities that allow spell resistance. Certain spells and effects function differently against it, as noted below. A magic missile paralyzes a sojourner (as the hold person spell) for 1 minute, with no saving throw. A magical attack that deals cold damage breaks any hold effect on the sojourner and heals 1 point of damage for each 3 points of damage the attack would otherwise deal. If the amount of healing would cause the sojourner to exceed its full normal hit points, it gains any excess as temporary hit points. A sojourner gets no saving throw against cold effects. A sojourner is unaffected by rust attacks, such as those of a rust monster or a rusting grasp spell."},{"type":"Powerful Blows","kind":"Ex","details":"A sojourner deals one and a half times its Strength modifier and threatens a critical hit on a 19-20 with its slam attacks."},{"type":"Resilient","kind":"Ex","details":"A sojourner gains bonus hit points as a construct as if it were two sizes larger."}],"description":"This metal construct, known as the sojourner of the sea, is believed to be one of a kind, and for that the civilized world is thankful. The sojourner is a man-shaped machine that constantly walks the ocean floor on an unknown quest, destroying anything that attempts to sway it from its inexorable path.\n\nThe sojourner was given its name by a maritime explorer who encountered it, fought it, and retreated with his life to tell the tale. No one knows the sojourner's real name, or even if it has one. The sojourner is fashioned from a special, highly resilient metal of unknown origin, its power source hidden somewhere deep inside its nearly impregnable frame. It continuously and unstoppably walks the lightless ocean floor, having traversed thousands of miles since it was first spotted years ago. So far it has proven indestructible. Its purpose remains a mystery. The symbols on its torso are as inscrutable as the sojourner itself.\n\nDuring its endless trek along the sea bed, if the sojourner encounters an obstacle it cannot pass through or climb over, it walks around the obstacle's perimeter or burrows beneath it, regardless of the distance required. It descends into the deepest ocean trenches and slowly advances up the far side. If a living being attempts to impede its progress, the sojourner attacks without hesitation, though it never initiates combat until it is touched or attacked. The unrelenting sojourner of the sea cannot swim. The creature is immune to the corroding and rusting effects of water.\n\nIn combat the sojourner is mindless, fearless, and unremitting. Once battle commences, the sojourner doesn't relent until all opponents are eliminated or have fled.","ecology":"","habitat_society":""},{"name":"Soul Reaper","cr":15,"xp":51200,"alignment":"NE","size":"Large","type":"undead","init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"see invisibility"}],"ac":29,"ac_touch":13,"ac_flat_footed":25,"ac_mods":"+4 Dex, +16 natural, -1 size","hp":231,"hd":"22d8+132","hdvalue":22,"fort":14,"ref":13,"will":18,"defensive_abilities":["channel resistance +4","inseparable weapon"],"dr":"15/silver and magic","immunities":["undead traits"],"sr":26,"speed":[{"type":"land","speed":40}],"melee":"+1 scythe +25 (2d6+13/19-20)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"soul slash"}],"spell_like_abilities_caster_level":22,"spell_like_abilities_concentration":22,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"see invisibility"}]},{"frequency":"at-will","spells":[{"spell":"desecrate"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"blindness/deafness"},{"spell":"symbol of pain"},{"spell":"unholy aura"}]}],"strength":27,"dexterity":19,"intelligence":18,"wisdom":21,"charisma":20,"baseatk":16,"cmb":25,"cmd":39,"feats":[{"feat":"Cleave"},{"feat":"Critical Focus"},{"feat":"Great Cleave"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (scythe)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (scythe)"}],"skills":[{"skill":"Climb","value":33},{"skill":"Diplomacy","value":14},{"skill":"Intimidate","value":30},{"skill":"Knowledge (arcana)","value":29},{"skill":"Knowledge (religion)","value":29},{"skill":"Perception","value":30},{"skill":"Sense Motive","value":30},{"skill":"Stealth","value":25},{"skill":"Survival","value":18}],"sq":[{"type":"inseparable weapon"}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This sinister figure appears shrouded in a long, black hooded robe. Its face is hidden from view and its long wickedly-curved claws are deathly black in color. It grips a gleaming, silver-bladed scythe in its claws.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Soul Slash","kind":"Su","details":"If a soul reaper scores a critical hit with its scythe, the target must succeed on a DC 26 Fortitude save or have its soul torn from its body and pulled into the soul reaper's scythe. If the save succeeds, the victim takes an extra 3d6 points of damage. A soul reaper's scythe can hold a number of souls equal to its Charisma bonus (four souls for a typical soul reaper). This effect is similar to a trap the soul spell. The save DC is Charisma-based. A creature's soulless body collapses into a desiccated husk, and in one day crumbles to dust. To reclaim a captured soul, the reaper must be destroyed and its scythe shattered on consecrated ground. When the scythe is shattered, all souls trapped are released and seek their original body (if it's been less than one day since the body was killed). Creatures without a body are left to wander in spirit form but can be returned to life through the successful casting of a miracle, wish, or true resurrection spell."},{"type":"Inseparable Weapon","kind":"Su","details":"A soul reaper has a mystic and magical connection to its scythe. If separated from its scythe (if the soul reaper is disarmed, for example) and within 100 ft. of it, it may summon it to its hands as a move action. If an opponent is holding the weapon when the reaper summons it, that opponent must succeed on a DC 26 Strength check or the weapon flies from its hands to the soul reaper. The check DC is Charisma-based."}],"description":"Soul reapers are vile undead with a fierce hatred for the living. They exist only to kill, and take great pleasure in slaying any living creature they encounter. They kill without guilt, without feeling or remorse, and without emotion; drinking the soul of their victim to insure it never returns to life.\n\nSoul reapers have no ties to the land of the living, in that they have always existed and have always been. Their origins are unknown, but speculation says they stepped from the great void at the beginning of creation. It is thought that only six or seven of these creatures exist (and most living beings are thankful of that).\n\nSoul reapers are 12-foot tall humanoid creatures shrouded in long, black hooded cloaks. Though they are corporeal creatures, their form is either shrouded in utter darkness or formed of the stuff of shadows.\n\nNo discernible facial features are visible under the hood. The creature's hands end in wicked claws of inky blackness that are always clutched tightly around its gleaming, sharp scythe. These creatures never speak and no one knows if they even can (and if they could, what would one say to a soul reaper?) Soul reapers haunt civilized lands searching for the next victim who will fall prey to the deadly scythe and its soul-draining powers. When it encounters a living creature, the soul reaper casts unholy aura on itself.\n\nIt then pinpoints an enemy spellcaster and uses its deafness ability, or selects the most powerful foe (its best guess) and hits it with blindness.\n\nInvisible opponents are no match for the soul reaper and it often targets them first, just to show them that they cannot hide from its deadly blade.\n\nWhen it closes to melee, the soul reaper uses a full attack with its scythe against its closest opponent.","ecology":"","habitat_society":"","gear":"+1 scythe"},{"name":"Addath","cr":16,"xp":76800,"alignment":"CE","size":"Huge","type":"aberration","init":6,"senses":[{"type":"blindsight","modifier":"60 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":28,"ac_touch":10,"ac_flat_footed":26,"ac_mods":"+2 Dex, +18 natural, -2 size","hp":220,"hd":"21d8+126","hdvalue":21,"fort":15,"ref":11,"will":14,"defensive_abilities":["bristles","spider poison immunity"],"dr":"15/ cold iron","resists":[{"type":"cold","value":20},{"type":"fire","value":20}],"sr":27,"speed":[{"type":"land","speed":40},{"type":"climb","speed":40}],"melee":"4 tentacles +24 (2d6+10 plus grab), bite +24 (4d6+10 plus poison)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"bristles"},{"type":"constrict","details":"2d6+10"},{"type":"poison"},{"type":"swallow whole","details":"4d6+15 acid damage, AC 19, 22 hp"}],"strength":31,"dexterity":15,"constitution":23,"intelligence":12,"wisdom":14,"charisma":14,"baseatk":15,"cmb":27,"cmb_special":"+4 vs. grapple","cmd":39,"cmd_special":"+12 vs. trip","feats":[{"feat":"Bleeding Critical"},{"feat":"Cleave"},{"feat":"Critical Focus"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (tentacle)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (bite)"},{"feat":"Weapon Focus (tentacle)"}],"skills":[{"skill":"Acrobatics","value":15},{"skill":"Climb","value":42},{"skill":"Escape Artist","value":26},{"skill":"Perception","value":26},{"skill":"Stealth","value":18},{"skill":"Survival","value":16}],"languages":["Common","Undercommon"],"environments":["any underground"],"organizations":["solitary"],"treasure":"standard","description_visual":"This creature appears to be a giant twenty-legged spider with no head. Its underside holds a large ravenous maw from which four long foul tentacles emerge.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Bristles","kind":"Ex","details":"Long bristles cover the addath's spidery legs. With the addath's erratic movements in combat, any creature adjacent to and attacking the addath has a chance of being hit by the bristles. Each time a creature attacks an addath with a melee attack it must make a DC 22 Reflex save to avoid being punctured by several bristles. Each time a creature is punctured by these bristles, it takes 1d6 points of piercing damage and is exposed to the addath's poison. A creature that grapples an addath is automatically hurt by these bristles. The save DC to avoid the bristles is Dexterity-based."},{"type":"Poison","kind":"Ex","details":"Bristles or bite-injury; save DC 26 Fort; frequency 1/round for 6 rounds; effect 1d6 Strength damage; cure 2 consecutive saves. The save DC is Constitution-based."},{"type":"Spider Poison Immunity","kind":"Ex","details":"An addath is immune to the venom of ordinary spiders, giant spiders, and phase spiders."},{"type":"Tentacles","kind":"Ex","details":"The addath's tentacles are always a primary attack for the creature. It can transfer a grabbed creature from a tentacle to its mouth as a move action."}],"description":"The addath is a fearsome subterranean hunter that makes its home in caves, caverns, and ruins. It is a highly aggressive predator that paralyzes its victim, carries it back to its nest, and devours it at its leisure.\n\nAddaths don't spin webs, but live in large tunnels and chambers or within ruined structures that can accommodate their massive size. Addath lairs are typically littered with the bones and carcasses of uneaten meals and so emanate the stench of death that is easily detectable (and functions as a warning to others not to intrude).\n\nAn addath stands almost 20 ft. tall. Its body is dark in color and covered with dark (usually black) hairs. Its legs are long and sleek and covered in deadly black bristles. The creature's mouth is located on its underside and is surrounded by four long tentacles. The tentacles are slick and hairless and either dark brown or black in color. The creature's eyes, tiny and almost undetectable are spaced evenly around its central form.\n\nAddaths, when hunting, attack from ambush, usually clinging to an overhang or ceiling and waiting for prey to pass beneath. Some prefer hiding in shadows and springing out when prey is detected, and still others prefer hiding in huge pits and holes, rushing forth whenever their tremorsense detects movement in the area. Addaths attack by grabbing their prey with their tentacles biting it repeatedly. Addaths try to stay in melee range at all times, knowing eventually a creature can't help but contact its poisonous bristles.","ecology":"","habitat_society":""},{"name":"Ancient Cloud Dragon","cr":16,"xp":76800,"alignment":"N","size":"Gargantuan","type":"dragon","subtypes":["air"],"init":4,"senses":[{"type":"cloud vision"},{"type":"dragon senses"}],"auras":["frightful presence (300 ft., DC 27)"],"ac":37,"ac_touch":6,"ac_flat_footed":37,"ac_mods":"+31 natural, -4 size","hp":297,"hd":"22d12+154","hdvalue":22,"fort":20,"ref":13,"will":21,"dr":"15/magic","immunities":["electricity","paralysis","sleep","winds"],"sr":27,"speed":[{"type":"land","speed":40},{"type":"fly","speed":250,"maneuverability":"clumsy"}],"melee":"bite +30 (4d6+18 plus 2d6 cold), 2 claws +30 (2d8+12), 2 wings +28 (2d6+6), tail slap +28 (2d8+18)","space":"20 ft.","reach":"15 ft. (20 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"60 ft. cone, DC 28, 20d6 cold plus bull rush [Medium or smaller]"},{"type":"cold bite","details":"2d6"},{"type":"crush"},{"type":"tail sweep"}],"spell_like_abilities_caster_level":22,"spell_like_abilities_concentration":29,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"call lightning"},{"spell":"control winds"},{"spell":"create water"},{"spell":"obscuring mist"},{"spell":"stinking cloud"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":14,"spellsknown_concentration":21,"spellsknown":[{"spell_level":7,"spell_slots":3,"spells":[{"spell":"reverse gravity"}]},{"spell_level":6,"spell_slots":6,"spells":[{"spell":"acid fog"},{"spell":"chain lightning"}]},{"spell_level":5,"spell_slots":7,"spells":[{"spell":"cloudkill"},{"spell":"cone of cold"},{"spell":"teleport"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"air walk"},{"spell":"dimension door"},{"spell":"ice storm"},{"spell":"lesser globe of invulnerability"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"dispel magic"},{"spell":"lightning bolt"},{"spell":"sleet storm"},{"spell":"wind wall"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"blur"},{"spell":"cat's grace"},{"spell":"invisibility"},{"spell":"levitate"},{"spell":"whispering wind"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"chill touch"},{"spell":"feather fall"},{"spell":"hypnotism"},{"spell":"shocking grasp"},{"spell":"unseen servant"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"detect magic"},{"spell":"daze"},{"spell":"mage hand"},{"spell":"message"},{"spell":"open/close"},{"spell":"ray of frost"},{"spell":"read magic"},{"spell":"resistance"}]}],"strength":35,"dexterity":10,"constitution":25,"intelligence":22,"wisdom":23,"charisma":22,"baseatk":22,"cmb":39,"cmd":47,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Flyby Attack"},{"feat":"Great Cleave"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Skill Focus (Fly)"},{"feat":"Snatch"},{"feat":"Wingover"}],"skills":[{"skill":"Bluff","value":31},{"skill":"Diplomacy","value":31},{"skill":"Fly","value":17},{"skill":"Intimidate","value":31},{"skill":"Knowledge (arcana)","value":31},{"skill":"Knowledge (geography)","value":31},{"skill":"Knowledge (history)","value":31},{"skill":"Knowledge (nature)","value":31},{"skill":"Perception","value":35},{"skill":"Sense Motive","value":35},{"skill":"Spellcraft","value":31},{"skill":"Use Magic Device","value":31}],"languages":["Auran","Aquan","Common","Draconic","Giant","Sylvan"],"sq":[{"type":"cloud form"}],"environments":["temperate mountains","warm mountains"],"organizations":["solitary","clan (2-5)"],"treasure":"triple standard","description_visual":"This dragon has a fringed and frilled head and wings that sweep back from its shoulders to its tail. Large, piercing rose colored eyes dominate its somewhat triangular head. Its tail trails off becoming misty and translucent near the tip.","group":"Dragon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"A cloud dragon's breath weapon is a powerful cone of icy cold air. When a cloud dragon uses its breath weapon, make a single bull rush attack using the dragon's CMB against the CMD of any creature that failed its Reflex save and is three or more size categories smaller than the dragon. This bull rush doesn't provoke attacks of opportunity, and the dragon cannot choose to move with any opponent pushed back. In addition to being pushed back, affected creatures are knocked prone and take 1d4 points of nonlethal damage per 10 ft. they are pushed back. Flying creatures are buffeted and pushed back twice the distance and sustain 1d6 points of nonlethal damage per 10 ft. they are pushed back."},{"type":"Cold Bite","kind":"Su","details":"At old age, a cloud dragon's bite deals an additional 2d6 points of cold damage. An ancient dragon's damage increases to 4d6, and a great wrym's to 6d6."},{"type":"Cloud Form","kind":"Su","details":"As a standard action, a juvenile or older cloud dragon can assume gaseous form at will, but it can remain gaseous indefinitely and has a fly speed of 20 ft. with perfect maneuverability."},{"type":"Cloud Vision","kind":"Ex","details":"A very young cloud dragon can see perfectly in foggy conditions (such as those created by fog cloud or obscuring mist)."},{"type":"Immunity to Winds","kind":"Su","details":"A cloud dragon is immune to the effects of wind. It ignores the penalties applied to the Fly skill incurred by wind speed, and is immune to the negative effects of any spell or effect that manipulates wind, such as gust of wind and whirlwind. Spell-like Abilities A cloud dragon gains the following spelllike abilities, usable at will upon reaching the listed age category. Young-create water; Juvenile-obscuring mist; Adult-stinking cloud; Old-call lightning; Ancient-control winds; Great Wyrm-control weather."},{"type":"Whirlwind","kind":"Sp","details":"A great wyrm cloud dragon can use this ability three times per day. It works as a whirlwind spell. This ability is the equivalent of an 8th-level spell."}],"description":"Cloud dragons are the most reclusive of all dragons, rarely leaving the safety and sanctity of their cloudy lairs. They have a great dislike for non-flying creatures and creatures that must use non-natural means to fly (such as through magical items or spells). A cloud dragon wyrmling's scales are silvery-blue with a slight hint of red at the tip of each scale. As the dragon ages, its color slowly changes to a bright sunset orange. The oldest cloud dragons resemble gold dragons, save for the large bony plates on their heads and backs. Cloud dragons are not highly aggressive, but dislike interlopers and attack them on sight. They open combat using their breath weapon, followed by their spell-like abilities. A cloud dragon rarely lands, preferring to fight from the air.","ecology":"","habitat_society":"","credit":"The Cloud Dragon originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Ancient Mist Dragon","cr":16,"xp":76800,"alignment":"N","size":"Gargantuan","type":"dragon","subtypes":["air","fire","water"],"init":3,"senses":[{"type":"dragon senses"},{"type":"mist vision"}],"auras":["frightful presence (300 ft., DC 29)"],"ac":37,"ac_touch":5,"ac_flat_footed":37,"ac_mods":"-1 Dex, +32 natural, -4 size","hp":324,"hd":"24d12+168","hdvalue":24,"fort":23,"ref":15,"will":23,"dr":"10/magic","immunities":["fire","paralysis","sleep"],"sr":27,"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":40},{"type":"fly","speed":250,"maneuverability":"clumsy"},{"type":"swim","speed":20}],"melee":"bite +32 (4d6+18 plus 4d6 fire), 2 claws +32 (2d8+12), 2 wings +30 (2d6+6), tail slap +30 (2d8+18)","space":"20 ft.","reach":"15 ft. (20 ft. with bite)","special_attacks":[{"type":"boiling bite"},{"type":"breath weapon","details":"cone, Fort DC 29, 10d6 fire plus blindness"},{"type":"crush"},{"type":"tail sweep"}],"spell_like_abilities_caster_level":24,"spell_like_abilities_concentration":31,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"control winds"},{"spell":"create water"},{"spell":"fog cloud"},{"spell":"solid fog"},{"spell":"wind wall"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":14,"spellsknown_concentration":21,"spellsknown":[{"spell_level":7,"spell_slots":4,"spells":[{"spell":"control weather"}]},{"spell_level":6,"spell_slots":6,"spells":[{"spell":"antimagic field"},{"spell":"globe of invulnerability"}]},{"spell_level":5,"spell_slots":7,"spells":[{"spell":"ice storm"},{"spell":"teleport"},{"spell":"true seeing"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"divination"},{"spell":"lesser globe of invulnerability"},{"spell":"rainbow pattern"},{"spell":"stoneskin"}]},{"spell_level":3,"spell_slots":8,"spells":[{"spell":"dispel magic"},{"spell":"displacement"},{"spell":"protection from energy"},{"spell":"speak with dead"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"comprehend languages"},{"spell":"daze monster"},{"spell":"detect thoughts"},{"spell":"protection from arrows"},{"spell":"see invisibility"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"burning hands"},{"spell":"magic missile"},{"spell":"mage armor"},{"spell":"obscuring mist"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"flare"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"message"},{"spell":"resistance"},{"spell":"touch of fatigue"}]}],"strength":35,"dexterity":8,"constitution":25,"intelligence":24,"wisdom":25,"charisma":24,"baseatk":24,"cmb":40,"cmd":49,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Combat Expertise"},{"feat":"Flyby Attack"},{"feat":"Great Fortitude"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Vital Strike"},{"feat":"Wingover"}],"skills":[{"skill":"Bluff","value":34},{"skill":"Diplomacy","value":34},{"skill":"Fly","value":12},{"skill":"Intimidate","value":34},{"skill":"Knowledge (arcana)","value":34},{"skill":"Knowledge (history)","value":34},{"skill":"Knowledge (nature)","value":34},{"skill":"Knowledge (religion)","value":34},{"skill":"Perception","value":38},{"skill":"Sense Motive","value":38},{"skill":"Spellcraft","value":34},{"skill":"Swim","value":47},{"skill":"Use Magic Device","value":34}],"languages":["Auran","Aquan","Celestial","Common","Draconic","Elf","Gnome","Ignan","Sylvan"],"sq":[{"type":"mist form"},{"type":"water breathing"}],"environments":["temperate aquatic","temperate forests","warm aquatic","warm forests"],"organizations":["solitary","clan (2-5)"],"treasure":"triple standard","description_visual":"This great dragon has a ridge of swept-back horns encircling its head with two larger and longer horns just above its eyes dominating the others. A ridge of similar smaller horns runs the length of its back from its shoulders to its tail. Its body is long, snake-like, and semi-material. It possesses no visible wings. Its scaled body is grayish-white.","group":"Dragon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Boiling Bite","kind":"Su","details":"At old age, a mist dragon's bite deals an additional 2d6 points of fire damage. An ancient dragon's damage increases to 4d6, and a great wrym's to 6d6."},{"type":"Breath Weapon","kind":"Su","details":"A mist dragon's breath weapon is a cone of cloudy scalding vapor. In still air, the vapor lingers for 1d4 rounds and forms a cloud that covers a radius equal to the cone's length; on the second round, the vapor condenses into a heated smothering fog that deals 1d6 points of fire damage to creatures each round they remain in the area (Fortitude save halves this damage). The fog also blinds creatures (as the blindness spell) that fail the save as long as they remain within in the cloud and for 2 rounds after they leave the area."},{"type":"Mist Form","kind":"Su","details":"As a standard action, a juvenile or older mist dragon can assume gaseous form, but it can remain gaseous indefinitely and has a fly speed of 20 ft. with perfect maneuverability. A great wyrm mist dragon's abilities while in mist form improve drastically. As a standard action a great wyrm mist dragon in mist form can make a single melee attack of its choice at its highest attack bonus. This attack deals normal damage. As a full-round action, a great wyrm mist dragon in mist form can attack with its breath weapon."},{"type":"Mist Vision","kind":"Ex","details":"A very young mist dragon can see perfectly in foggy conditions (such as those created by fog cloud or obscuring mist). Spell-like Abilities A mist dragon gains the following spelllike abilities, usable at will upon reaching the listed age category. Young-create water; Juvenile-fog cloud; Adult-wind wall; Old-solid fog; Ancient-control winds; Great Wyrm-control water."},{"type":"Water Breathing","kind":"Ex","details":"A very young or older mist dragon can breathe underwater indefinitely and can freely use its breath weapon, spells, and other abilities while submerged."}],"description":"Mist dragons are relatively passive (for dragons) and reclusive, preferring to spend their time away from most other races (including other mist dragons). Mist dragons make their lairs near large sources of water such as waterfalls, lakes, and seashores. A mist dragon resembles a gold dragon in shape and size. Its scales are shiny-blue white as a hatchling and gradually darken to a blue-gray color with metallic silver splotches. Mist dragons usually spend their days moving from place to place in mist form. If threatened or angered, a mist dragon assumes solid form and attacks using its breath weapon, claws, and bite.","ecology":"","habitat_society":"","credit":"The Mist Dragon originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Black Rot","cr":16,"xp":76800,"alignment":"N","size":"Medium","type":"vermin","subtypes":["swarm"],"init":5,"senses":[{"type":"lifesense","modifier":"60 ft."}],"ac":15,"ac_touch":15,"ac_flat_footed":10,"ac_mods":"+5 Dex","hp":108,"hd":"24d8","hdvalue":24,"hp_mods":["fast healing 10"],"fort":14,"ref":13,"will":8,"defensive_abilities":["evasion"],"immunities":["mind-affecting effects","weapon damage","swarm traits","vermin traits"],"weaknesses":["swarm traits","vulnerability to remove disease"],"speed":[{"type":"fly","speed":10,"maneuverability":"perfect"}],"melee":"swarm (disease)","space":"5 ft.","reach":"0 ft.","special_attacks":[{"type":"disease"},{"type":"distraction","details":"DC 22"}],"dexterity":21,"constitution":10,"wisdom":10,"charisma":1,"baseatk":18,"feats":[{"feat":"Ability Focus (disease)","type":"bonus"}],"skills":[{"skill":"Fly","value":13},{"skill":"Stealth","value":5,"special":"+21 in darkness"}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"A cloud rises before you like a dark smear in the air, the smell of death in its wake.","group":"Living Disease","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Disease","kind":"Ex","details":"Black Rot: This highly infectious disease affects the skin and muscles of the victim, creating an accelerated gangrenous process that turns the affected tissue black and eats it away. For every 4 points of Con damage sustained by the victim, a random limb is lost and can only be recovered by regeneration or similar magic. Black Rot: Swarm—contact; save DC 29 Fort; onset immediate; frequency 1/ day; effect 1d6 Con damage, 1d6 Dex damage, and 1d3 Cha damage; cure 2 consecutive saves. The save DC is Dexterity-based."}],"description":"Living diseases are swarms of microscopic organisms, harmful bacteria or viruses that have supernaturally gained limited sentience as a cohesive swarm under certain exceedingly foul or magical conditions. They seek out hosts through which to propagate their contagion. Though they are considered swarms, their individual components are so small as to be invisible to unaided sight, exponentially smaller than even Fine creatures, and they are thus considered one Medium creature. They are only visible at all due to the sheer number of individual organisms that comprise the swarm; literally billions of them make up a single living disease.\n\nLiving diseases offer no resistance to items or creatures entering their midst and cannot be physically felt. They make no sound whatsoever. A living disease in the dark is terrible indeed, as there is no indication it is present until its effects are first felt.\n\nLiving diseases neither see nor sleep. Their movements are by pure instinct, and they locate potential hosts with their lifesense. Because of their resilience and extremely high reproductive rate, the microorganisms of a living disease give it fast healing 10.\n\nThough extremely rare, there are many different kinds of living diseases - potentially as many kinds as there are diseases. Two in particular are described here: festering lung and black rot.\n\nA living disease seeks to surround any potential host it senses. It instinctively avoids undead, oozes, plants and constructs, which don't make suitable hosts for the spreading of disease. Unlike normal swarms, a living disease doesn't deal physical damage. Instead it exposes any creature whose space it occupies at the end of its move to its form of disease.","ecology":"","habitat_society":"","credit":"Original author Greg A. Vaughan  Originally appearing in Slumbering Tsar (© Frog God Games/ Greg A. Vaughan, 2012)"},{"name":"Caizel (Deposed Queen of Succubi)","cr":16,"xp":76800,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":36,"ac_touch":24,"ac_flat_footed":30,"ac_mods":"+6 Dex, +12 natural, +8 profane","hp":207,"hd":"18d10+108","hdvalue":18,"fort":17,"ref":14,"will":20,"dr":"15/cold iron and good","immunities":["electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":27,"speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"+2 dagger +27 (2d4+8/19-20) or 2 claws +25 (1d6+6) or melee touch +24 (touch of ecstasy)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"poison"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":26,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"charm monster"},{"spell":"darkness"},{"spell":"desecrate"},{"spell":"detect good"},{"spell":"detect law"},{"spell":"detect thoughts"},{"spell":"doom"},{"spell":"ethereal jaunt","details":"self plus 50 pounds of objects only"},{"spell":"greater teleport","details":"self plus 50 pounds of objects only"},{"spell":"read magic"},{"spell":"suggestion"},{"spell":"tongues","details":"self only"}]},{"frequency":"1/day","spells":[{"spell":"magic circle against good"},{"spell":"mirror image"},{"spell":"summon","details":"level 9, 1d6 succubi or 1d2 hezrous 100% or 1d4 chaaors 70%"}]},{"frequency":"3/day","spells":[{"spell":"greater dispel magic"},{"spell":"protection from good"},{"spell":"unholy blight"},{"spell":"wall of fire"}]}],"strength":23,"dexterity":22,"constitution":23,"intelligence":25,"wisdom":25,"charisma":27,"baseatk":18,"cmb":24,"cmd":48,"feats":[{"feat":"Alertness"},{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Deceitful"},{"feat":"Flyby Attack"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Weapon Focus (claw)"},{"feat":"Weapon Focus (dagger)"}],"skills":[{"skill":"Bluff","value":33},{"skill":"Diplomacy","value":29},{"skill":"Disguise","value":33},{"skill":"Escape Artist","value":27},{"skill":"Fly","value":31},{"skill":"Intimidate","value":26},{"skill":"Knowledge (planes)","value":28},{"skill":"Perception","value":40},{"skill":"Perform (acting)","value":26},{"skill":"Perform (dancing)","value":29},{"skill":"Sense Motive","value":32},{"skill":"Stealth","value":27},{"skill":"Survival","value":25}],"languages":["Abyssal","Celestial","Common","Infernal","Sylvan","Undercommon","telepathy 100 ft."],"environments":["any (Abyss)"],"organizations":["solitary","troupe (Caizel plus 2-5 succubi)"],"treasure":"standard","description_visual":"This astonishingly beautiful creature stands about 6 ft. tall. Her skin is copper in color and her eyes are blue-green. She has long raven-black hair and her hands end in sharpened claws. She is clad in a robe of gold.","group":"Demon Lord","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Caizel's body courses with a virulent poison that she can intensify or suppress at will. It isn't secreted through her skin (therefore her touch isn't poisonous); rather it is delivered through the exchange of body fluids with another creature (kissing, consummating an encounter, etc.). If a target isn't willing to be kissed, she must start a grapple to do so. Caizel's Poison: Kiss-contact; save Fort DC 25; frequency 1/round for 6 rounds; effect 1d8 Con damage; cure 2 consecutive saves. The save DC is Constitution-based."},{"type":"Touch of Ecstasy","kind":"Su","details":"Once per round, by making a melee touch attack against a foe, Caizel can flood the creature's mind with the most pleasurable images it can conjure if it fails a DC 25 Will save. This effect stuns the creature for 1d4 rounds while its mind processes the information. A creature that successfully saves cannot be affected by Caizel's touch of ecstasy for one day. The save DC is Constitution-based. Caizel can suppress this ability at will. Bonerazor: Bonerazor is a finely crafted and perfectly balanced +2 dagger. Because of its expert craftsmanship it deals 2d4 points of damage on a successful hit. Additionally, a creature hit must make a DC 25 Fortitude save or be held (as by a hold person spell, CL 20th). The creature can make a new save each round to escape. A creature remains held as long as Bonerazor remains embedded in its body or until it makes a successful Fortitude save. So long as Caizel is within 50 ft. of it, she can command the dagger to return to her hand as a free action."}],"description":"Caizel is an exquisitely beautiful demoness known throughout the planes for her ability to seduce just about any being she desires. Many dukes of Hell and lords of the Abyss have fallen prey to her; some have met their demise at her hands as well. She was once the concubine of a demon lord (some say it was Kostachard) and self-styled Queen of the Succubi, but he grew displeased with her after she killed several of his other concubines and targeted her for death. She fought back and managed to slay the demon lord before making her escape. She now resides on her own and serves no one, though she does often sell her services to a demon prince or lord who wishes to employ her for some scheme or plot. Caizel detests Beluiri and would like nothing more than to destroy her. Likewise, Beluiri would like to see Caizel gone once and for all. Beluiri once worked with Caizel on a mission to seduce a powerful demon prince. When the ruse was discovered, Beluiri betrayed Caizel; leaving her to the devices of the prince and his fiendish minions. Thinking her gone, Beluiri began calling herself \"The Temptress\" and touted herself as the seductress of the lower planes. Since Caizel's return, she has attempted to reclaim that title and now seeks revenge against Beluiri. Caizel is an astonishing beautiful creature standing just under 6 ft. tall. Her skin is delicate, soft, and copper in color. Her eyes are blue-green. Two tiny horns are hidden beneath her long, raven-black hair. Her hands, while clawed, are shapely and delicate. Small leather wings protrude from her back, but she usually keeps these hidden beneath her robes and gowns. Caizel prefers clothes of gold, silver, sapphire, or black. Caizel tries to avoid melee combat if possible, preferring to use her skills and abilities against a lone target that she can easily manipulate and control. If forced into combat, she immediately uses her summon demons ability to summon a pack of hezrous to her aid. After summoning her demonic allies, she throws up a protection from good or magic circle against good and uses her wall of fire ability against her aggressors. In battle, she uses her touch of ecstasy ability to disable opponents and then finishes them off with a kiss or allows her comrades to finish them off. If combat is going against her, she uses her ethereal jaunt or greater teleport to escape.","ecology":"","habitat_society":"","gear":"Bonerazor"},{"name":"Ciratto","cr":16,"xp":76800,"alignment":"CE","size":"Large","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"see invisibility"}],"auras":["unholy aura (DC 24)"],"ac":29,"ac_touch":14,"ac_flat_footed":24,"ac_mods":"+5 Dex, +15 natural, -1 size","hp":187,"hd":"15d10+105","hdvalue":15,"fort":12,"ref":14,"will":17,"dr":"10/good","immunities":["electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":27,"speed":[{"type":"land","speed":60}],"melee":"mwk heavy mace +23 (2d6+8/19- 20), 4 snakes +18 (1d6 plus poison), 2 hooves +17 (1d6+8)","ranged":"composite longbow +19 (2d6+8)","space":"10 ft.","reach":"5 ft.","spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":22,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"see invisibility"},{"spell":"unholy aura"}]},{"frequency":"at-will","spells":[{"spell":"call lightning"},{"spell":"greater dispel magic"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"slow"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"blasphemy"},{"spell":"summon","details":"level 5, 1 ciratto 20%, 1 nalfeshnee 35%, or 1d6 glabrezus 60%"}]}],"strength":27,"dexterity":21,"constitution":25,"intelligence":21,"wisdom":22,"charisma":22,"baseatk":15,"cmb":24,"cmd":39,"cmd_special":"+4 vs. trip","feats":[{"feat":"Cleave"},{"feat":"Critical Focus"},{"feat":"Great Cleave"},{"feat":"Improved Critical (heavy mace)"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (snakes)"}],"skills":[{"skill":"Bluff","value":24},{"skill":"Diplomacy","value":24},{"skill":"Escape Artist","value":20},{"skill":"Intimidate","value":24},{"skill":"Knowledge (arcana)","value":20},{"skill":"Knowledge (planes)","value":23},{"skill":"Perception","value":24},{"skill":"Sense Motive","value":24},{"skill":"Stealth","value":23},{"skill":"Survival","value":24},{"skill":"Use Magic Device","value":24}],"languages":["Abyssal","Celestial","Common","Draconic","telepathy 100 ft."],"environments":["any (Abyss)"],"organizations":["solitary","troop (1 ciratto and 1-4 glabrezu)"],"treasure":"standard (masterwork heavy mace, composite longbow)","description_visual":"This powerful entity has the lower torso of a black horse and the upper torso of a charcoal-colored humanoid. Its eyes blaze the color of fire and two downward curving horns protrude from its head. Four long, sinewy snakes seem to grow from the humanoid back of this creature.","group":"Demon","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save DC 24 Fort; frequency 1/round for 6 rounds; effect 1d2 Constitution damage; cure 2 saves. The save DC is Constitution-based."}],"description":"Ciratto demons are bred for combat, and as such are often found leading other demonic troops in battle. Cirattos can be found on any of the Abyssal layers in the employ of numerous lords and nobles. When not carrying out the orders of their master, they often spend their time hunting lesser demons and adventurers foolish enough to wander into the Abyss.\n\nCiratto demons are centaur-like demons with the lower torso of a black horse and the upper torso of a dark-skinned demon. Its head sports two large gray horns and its mouth is lined with small needle-like teeth. Four large poisonous dark mottled vipers grow from its back. A ciratto demon stands over 8 ft. tall and weighs around 2,500 pounds.\n\nCiratto demons enjoy wading into battle. They attack with an array of weapons including maces, morningstars, and spiked clubs. In combat, they quickly close ranks with their opponents after unleashing a barrage of spell-like abilities so they can use their hooves and poisonous snakes. Slain foes are usually devoured immediately. Those not eaten, or parts of creatures not eaten, are left for scavengers. Ciratto, while they enjoy hunting devils, never eat their flesh, finding it disgusting to both smell and taste.","ecology":"","habitat_society":""},{"name":"Flayed Angel","cr":16,"xp":76800,"alignment":"NE","size":"Large","type":"undead","subtypes":["extraplanar"],"init":8,"senses":[{"type":"blindsight","modifier":"120 ft."}],"ac":32,"ac_touch":24,"ac_flat_footed":27,"ac_mods":"+4 Dex, +1 dodge, +8 natural, +10 profane, -1 size","hp":252,"hd":"24d8+120 (+24)","hdvalue":24,"fort":17,"ref":14,"will":19,"defensive_abilities":["channel resistance +6","profane presence"],"dr":"10/evil","immunities":["acid","undead traits"],"sr":27,"speed":[{"type":"land","speed":40}],"melee":"2 slams +25 (2d6+7/19-20 plus 2d6 acid)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"gout of blood"},{"type":"rend","details":"2 slams, 3d6+10 plus 2d6 acid"}],"strength":25,"dexterity":18,"intelligence":6,"wisdom":16,"charisma":21,"baseatk":18,"cmb":26,"cmd":51,"feats":[{"feat":"Cleave"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (slam)"},{"feat":"Improved Initiative"},{"feat":"Improved Natural Attack (slam)"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Skill Focus (Acrobatics)"},{"feat":"Spring Attack"},{"feat":"Toughness"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Acrobatics","value":34,"special":"+46 jump"},{"skill":"Climb","value":22},{"skill":"Perception","value":18}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This once angelic being has been reduced to a twisted mass of oozing, raw flesh and muscle tissue, every bit of the skin having been stripped away from the body. The neck ends at a jagged stump, and the tattered, shredded remains of once-beautiful wings extend behind it.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Gout of Blood","kind":"Ex","details":"Whenever a flayed angel is physically struck in battle, the impact causes a spray of acidic blood to fly off the creature at anyone within 5 ft. Anyone in the area of affect must make a DC 24 Reflex save or take 1d6 points of acid damage from this splatter. The save DC is Dexterity-based."},{"type":"Profane Presence","kind":"Su","details":"The existence of a flayed angel is such an anathema to the order of the multiverse that its very presence is a profanity of nature. This presence provides it with a +10 profane bonus to Armor Class and a +2 profane bonus to its saves."}],"description":"On some rare occasions when an extremely powerful angel is captured, tortured to death and subjected to particularly vile rituals, dark gods of evil will intervene and prevent that being's essence from returning to its celestial home, instead trapping it within the mutilated corpse as a horrifyingly profane undead abomination. Such creations are anathema to the heavenly hosts and are actively hunted down by angles and archons whenever their existence is discovered. They seek to erase the stain upon the forces of good by the perversion of such a champion and to release its essence back to its rightful plane.\n\nA flayed angel is horribly mutilated, its skin flayed away, its wings crippled, and its head removed. The preparation ritual also involves the introduction of an acidic embalming fluid that mingles with the blood left in its body as a continually-leaking, caustic brew.\n\nA flayed angel stands around 8 ft. tall due to the removal of its head and weighs about 450 pounds.\n\nFlayed angels have lost most of their original battle prowess becoming little more than lumbering death dealers. However, they are still quite agile and, as former flyers of great renown, are still expert jumpers. They often climb to a higher position in order to leap down on their foes and attack in a sad caricature of their former ability to swoop down upon enemies from above. Regardless, their attacks soon devolve into brutish attempts to rend their foes into unrecognizable hunks of meat.\n\nThey strangely retain their inherent damage reduction that can only be overcome by evil-aligned weapons, often making them difficult and confusing foes. Their natural attacks are no longer considered good-aligned for the purpose of overcoming damage reduction.\n\nThe acidic blood mixture that continually oozes through their bodies splatters upon a foe on a successful melee hit and deals acid damage as well.","ecology":"","habitat_society":"","credit":"Original author Greg A. Vaughan  Originally appearing in Slumbering Tsar (© Frog God Games/ Greg A. Vaughan, 2012)"},{"name":"Ghaddar Devil","cr":16,"xp":76800,"alignment":"LE","size":"Huge","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":9,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"see in darkness"}],"ac":33,"ac_touch":13,"ac_flat_footed":28,"ac_mods":"+5 Dex, +20 natural, -2 size","hp":200,"hd":"16d10+112","hdvalue":16,"hp_mods":["regeneration 5 (good, silver)"],"fort":14,"ref":15,"will":12,"dr":"10/good and silver","immunities":["fire","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"sr":27,"speed":[{"type":"land","speed":40}],"melee":"2 claws +26 (2d6+11 plus grab), bite +25 (2d8+11 plus  vorpal bite)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"feed"}],"spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":23,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"}]},{"frequency":"at-will","spells":[{"spell":"greater teleport","details":"self plus 50 pounds of objects only"},{"spell":"persistent image"},{"spell":"unholy aura"},{"spell":"wall of fire"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 8, 2d10 lemures or 1d6 bearded devils 50%; or 1d6 barbed devils 35%; or 1 horned devil or ghaddar devil 20%"}]},{"frequency":"3/day","spells":[{"spell":"fireball"},{"spell":"lightning bolt"}]}],"strength":33,"dexterity":21,"constitution":24,"intelligence":12,"wisdom":14,"charisma":18,"baseatk":16,"cmb":29,"cmd":44,"feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Climb","value":30},{"skill":"Intimidate","value":23},{"skill":"Knowledge (planes)","value":20},{"skill":"Perception","value":25},{"skill":"Sense Motive","value":25},{"skill":"Stealth","value":16},{"skill":"Survival","value":21}],"languages":["Common","Infernal","telepathy 100 ft."],"environments":["any (Hell)"],"organizations":["solitary","troupe (2-4)"],"treasure":"none","description_visual":"This massive creature stands almost three times as tall as a human and has the head of a donkey. It shuffles with a hunched gait as it moves.  Large downward-curving horns protrude from its head. Its body is covered with blackish hair. Its ft. are splayed and its eyes are stark white with hollow black pupils.","group":"Devil","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Feed","kind":"Su","details":"When a ghaddar slays a humanoid opponent, it can feed on the corpse, devouring both flesh and life force, as a full-round action. Feeding destroys the victim's body and prevents any form of raising and resurrection that requires part of the corpse. There is a 50% chance that a wish, miracle, or true resurrection spell can restore a devoured victim to life. Check once for each destroyed creature. If the check fails, the creature cannot be brought back to life by mortal magic. A ghaddar advances in Hit Dice by consuming corpses in this fashion. For every three suitable corpses a ghaddar devours, it gains 1 Hit Die, and its Strength, Constitution, and natural armor increase by +1. Its attack bonus and saves improve as normal for an outsider of its Hit Dice, and it gains skill points, feats, and ability score improvements normally. The ghaddar only advances by consuming the corpses of creatures whose Hit Dice or levels are equal to or greater than its own current total."},{"type":"Vorpal Bite","kind":"Ex","details":"If a ghaddar scores a natural 20 on its attack roll with its bite attack and confirms the critical hit, it severs the foe's head."}],"description":"The terrible and mighty ghaddars roam the planes of Hell devouring the unfortunate souls of those they encounter. They also consume the essence and being of any outcast devils and dukes that cross their path.\n\nA typical ghaddar stands 15 ft. tall and weighs 6,000 pounds.\n\nA ghaddar assails its foes with a barrage of claw attacks. A grabbed opponent is bitten and, if slain, devoured. Ghaddar are not strategists, and unless directed by a commander or captain, they attack with little organization and finesse. The ferocity of the ghaddar is unparalleled in combat.","ecology":"","habitat_society":""},{"name":"Ha-Naga","cr":16,"xp":76800,"alignment":"CE","size":"Huge","type":"aberration","init":10,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"see invisibility"}],"ac":31,"ac_touch":15,"ac_flat_footed":24,"ac_mods":"+6 Dex, +1 dodge, +16 natural, -2 size","hp":250,"hd":"20d8+160","hdvalue":20,"fort":14,"ref":14,"will":15,"dr":"10/magic","immunities":["charm","sleep"],"resists":[{"type":"cold","value":20},{"type":"fire","value":20}],"sr":27,"speed":[{"type":"land","speed":50},{"type":"fly","speed":80,"maneuverability":"good"}],"melee":"bite +21 (2d8+8), sting +21 (1d8+8 plus poison), tail slap +19 (2d6+4 plus grab)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"charming gaze"},{"type":"constrict","details":"2d6+8"},{"type":"poison"}],"spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":27,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"see invisibility"}]},{"frequency":"3/day","spells":[{"spell":"plane shift","details":"self plus willing targets only"}]}],"spellsknown_caster_level":15,"spellsknown_concentration":27,"spellsknown":[{"spell_level":7,"spell_slots":5,"spells":[{"spell":"finger of death"},{"spell":"prismatic spray"}]},{"spell_level":6,"spell_slots":7,"spells":[{"spell":"chain lightning"},{"spell":"summon monster VI"},{"spell":"true seeing"}]},{"spell_level":5,"spell_slots":7,"spells":[{"spell":"baleful polymorph"},{"spell":"feeblemind"},{"spell":"symbol of sleep"},{"spell":"teleport"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"bestow curse"},{"spell":"fear"},{"spell":"greater invisibility"},{"spell":"wall of fire"}]},{"spell_level":3,"spell_slots":8,"spells":[{"spell":"dispel magic"},{"spell":"hold person"},{"spell":"magic circle against good"},{"spell":"sleet storm"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"blindness-deafness"},{"spell":"blur"},{"spell":"gust of wind"},{"spell":"invisibility"},{"spell":"shatter"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"chill touch"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"protection from good"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"bleed"},{"spell":"daze"},{"spell":"detect magic"},{"spell":"flare"},{"spell":"message"},{"spell":"open/close"},{"spell":"read magic"},{"spell":"touch of fatigue"}]}],"strength":27,"dexterity":23,"constitution":26,"intelligence":24,"wisdom":26,"charisma":24,"baseatk":15,"cmb":10,"cmd":28,"feats":[{"feat":"Alertness"},{"feat":"Combat Casting"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Eschew Materials"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Multiattack"}],"skills":[{"skill":"Acrobatics","value":25},{"skill":"Bluff","value":27},{"skill":"Diplomacy","value":27},{"skill":"Fly","value":24},{"skill":"Intimidate","value":25},{"skill":"Knowledge (arcana)","value":30},{"skill":"Knowledge (nobility)","value":27},{"skill":"Knowledge (planes)","value":27},{"skill":"Perception","value":35},{"skill":"Sense Motive","value":32},{"skill":"Spellcraft","value":30},{"skill":"Stealth","value":21,"special":"+29 blending"}],"languages":["Abyssal","Celestial","Common","Draconic","Giant","Infernal","any one elemental language (Aquan, Auran, Ignan, Terran)"],"environments":["any temperate land","any warm land","any underground"],"organizations":["solitary"],"treasure":"double standard","description_visual":"This enormous snake-like creature has the head of a gigantic humanoid.","group":"Naga","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Charming Gaze","kind":"Su","details":"This ability functions as a charm monster spell (CL 20th); 90 ft.; DC 27 Will negates. The save DC is Charisma-based."},{"type":"Poison","kind":"Ex","details":"Sting-injury; save DC 28 Fort; frequency 1/round for 6 rounds; effect 1d6 Con damage; cure 2 consecutive saves. The save DC is Constitution-based."}],"description":"The ha-naga is a stronger, fiercer version of the more common naga that spends its time moving from plane to plane, engaging in diplomacy, courtly intrigues and plotting, and even hunting (both for sport and for food). These creatures are known for their voracious appetites, eating anything, both alive or dead, except for others of their own kind (even in times of starvation).\n\nHa-nagas lair in deep, dark caves or ruins, far away from most civilized lands. A typical ha-naga lair is a twisted maze of tunnels and chambers with multiple entry and exit points, all camouflaged and trapped with both mundane and magical traps.\n\nHa-nagas are generally solitary creatures but can occasionally be encountered with other nagas of evil disposition. These creatures sometimes make truces with local evil humanoids (gnolls, inphidians especially, or hobgoblins) allowing the humanoids to serve them or in some cases even worship them as gods, and exchanging gifts and treasure for knowledge, food, and other goods.\n\nA typical ha-naga stretches over 20 ft. and weighs over 600 pounds. Larger versions are known to exist. They are stronger and smarter than the ha-naga presented here. One unique ha-naga of Colossal size, Sss'ashisth, dwells in the fabled City of Brass, spending his days in the court of the Sultan. (See the City of Brass boxed set from Necromancer Games for details.)","ecology":"","habitat_society":""},{"name":"Jade Colossus","cr":16,"xp":76800,"alignment":"N","size":"Colossal","type":"construct","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":34,"ac_touch":2,"ac_flat_footed":34,"ac_mods":"+32 natural, -8 size","hp":256,"hd":"32d10+80","hdvalue":32,"fort":10,"ref":10,"will":10,"defensive_abilities":["light reflection"],"dr":"15/adamantine","immunities":["construct traits","fire","magic"],"speed":[{"type":"land","speed":40}],"melee":"2 slams +43 (4d8+19)","space":"30 ft.","reach":"30 ft.","special_attacks":[{"type":"breath weapon"}],"strength":49,"dexterity":10,"wisdom":11,"charisma":1,"baseatk":32,"cmb":59,"cmd":69,"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This massive automaton stands five times as tall as a normal human and resembles a gigantic humanoid carved of smooth green stone.","group":"Colossus","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"Once every 1d4 rounds, a jade colossus can spray a blast of green energy in either a 60-foot cone or a 120-foot line. A creature in the affected area takes 15d6 points of damage, Reflex half DC 26. A creature slain as the result of this breath weapon transforms into jade. The save DC is Constitution-based. A creature turned to jade has Hardness 6, hp 40. This effect can be reversed by casting stone to flesh, wish, or miracle. The victim remains dead, but can then be raised or resurrected normally."},{"type":"Immunity to Magic","kind":"Ex","details":"A jade colossus is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against the creature, as noted below. A disintegrate spell slows a jade colossus (as the slow spell) for 1d6 rounds, with no saving throw. A shatter spell deals 3d12 points of damage to a jade colossus, with no saving throw. A magical attack that deals fire damage breaks any slow effect on the jade colossus and heals 1 point of damage for each 3 points of damage the attack would otherwise deal. If the amount of healing would cause the golem to exceed its full normal hit points, it gains any excess as temporary hit points. A jade colossus gets no saving throw against fire effects."},{"type":"Light Reflection","kind":"Ex","details":"The angles and makeup of the jade colossus allows it to reflect any light-based attacks or effects (it cannot reflect natural sunlight however). Reflected light acts as an emanation (lasting 1 round) that blinds all creatures within 40 ft. A creature can attempt a Reflex save DC 26 to avoid being blinded If the save fails, the creature is blinded for 2d4 rounds (as the blindness spell); creatures that successfully save are instead dazzled for a like amount of time. Undead and similar creatures to whom sunlight is harmful to take 6d6 points of damage (a successful Reflex save DC 26 halves the damage)."}],"description":"The jade colossus was first seen dominating the skyline over the City of Brass, its massive form reflecting the light from the ever-burning fires of the City. Since that time, rumors of these creatures moving across the Material Plane have been heard in taverns and inns. Jade colossi are massive constructs built by powerful spellcasters to do their bidding; typically for protection or to wage war against an archrival. A jade colossus pummels a foe with its hardened fists; dealing massive amounts of damage with every successful strike. It almost always opens combat with its breath weapon. A typical jade colossus stands 35 ft. tall and weighs about 60,000 pounds. (The jade colossus spotted in the City of Brass is thought to be over 50 ft. tall and weigh in excess of 100,000 pounds.) Ruby Star of Law Sages speak of a jade colossus located in the City of Brass that has the ruby star of law (a gem of inestimable value) embedded in its forehead. The Jade Guardian (as it is known in the City) is a CR 18 advanced jade colossus with the following additional ability. Energy Ray (Su): Once per round as a swift action, the Jade Guardian can fire a ray to a range of 200 ft. (requires a successful ranged touch attack to hit). Genies hit by this ray must make a successful Fortitude save (DC 26) or take 6d4 points of Constitution damage. On a successful save, the genie takes onehalf damage. Other creatures are affected as follows: Lawful creatures are slowed (as by the slow spell) for 1d4 rounds (no save). Non-lawful creatures take 6d6 points of force damage (no save) and are stunned for 1d4 rounds (DC 26 Fortitude save negates). Should the ruby star of law ever be claimed as a magic item, treat it as a minor artifact that allows use of the energy ray ability indicated above, save that it requires a standard action to activate. Construction A jade colossus's body is constructed from 80,000 pounds of pure jade, and a mixture of rare stones, herbs, and chemicals totaling 8,000 gp. JADE COLOSSUS CL 15th; Price 110,000 gp Requirements Craft Construct, blindness, flesh to stone, geas/quest, polymorph any object, creator must be caster level 15th; Skill Craft (sculptures) DC 30; Cost 59,000 gp","ecology":"","habitat_society":""},{"name":"Kulgreer","cr":16,"xp":76800,"alignment":"N","size":"Gargantuan","type":"aberration","subtypes":["aquatic"],"init":4,"senses":[{"type":"blindsight","modifier":"120 ft."},{"type":"darkvision","modifier":"60 ft."}],"ac":22,"ac_touch":6,"ac_flat_footed":22,"ac_mods":"+16 natural, -4 size","hp":252,"hd":"24d8+144","hdvalue":24,"fort":16,"ref":10,"will":16,"dr":"20/magic","sr":27,"speed":[{"type":"swim","speed":50}],"melee":"slam +27 (4d6+18/19-20)","space":"20 ft.","reach":"15 ft.","special_attacks":[{"type":"vortex"}],"strength":34,"dexterity":10,"constitution":22,"intelligence":10,"wisdom":11,"charisma":14,"baseatk":18,"cmb":34,"cmd":44,"cmd_special":"can't be tripped","feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Great Fortitude"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (slam)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Skill Focus (Swim)"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Escape Artist","value":15},{"skill":"Intimidate","value":29},{"skill":"Knowledge (arcana)","value":12},{"skill":"Perception","value":27},{"skill":"Swim","value":53}],"languages":["Common (can't speak)"],"environments":["any oceans"],"organizations":["solitary"],"treasure":"none","description_visual":"This is a macabre creature, possessing no evident features common to other living creatures such as a cranium, appendages, or eyes. It has a long, conical body and a horrific gaping maw.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Vortex","kind":"Su","details":"Three times per day, a kulgreer can create a powerful, self-contained whirlpool within its conical frame. This lasts for 1d6+6 rounds. Huge and smaller creatures within 20 ft. of the kulgreer must succeed on a DC 34 Swim check or be yanked into the 30-foot diameter mouth of the whirlpool. As the whirlpool spirals through the kulgreer's frame, creatures inside are thrashed violently about taking 2d6+18 points of damage each round. A successful DC 34 Reflex save or DC 34 Swim check negates the damage for that round and allows the trapped creature to escape. The save DCs are Strength-based. During the final round of the vortex's duration, any creatures still trapped are pulled through the sphere of dim, white light in the kulgreer's tapered outlet. Such creatures must succeed on a DC 28 Fortitude save or take 12d6 points of damage. Those succeeding on their save take only half damage and are forcibly ejected from the kulgreer and flung 40 ft. away. There is a 5% chance that any ejected creature is instead sent to a random plane of existence (GM's choice as to which one). The save DC is Constitution-based."}],"description":"The kulgreer is a massive, abominable being of the deep sea that creates powerful whirlpools inside its funnel-like body. It has a 30 foot long, conical body resembling a funnel, beginning in a wide mouth 30 ft. in diameter, and tapering into a 5 foot diameter outlet of dim, white light.\n\nThe kulgreer navigates the depths in a non-cognizant state, pointed-end first; its conical body gradually rotates and propels itself forward subconsciously, amassing various creatures into its frame as it passes through. If awakened from this state, the kulgreer is generally violent. It is popular belief that creatures sucked into the kulgreer's funnel-like body are teleported to another plane of existence.\n\nThough not consciously aggressive, the circumstances presented through a kulgreer's presence inevitably lead to conflict. If provoked, the kulgreer typically tramples its opponent in a fit of sudden sentience and conclude in the use of its supernatural ability.","ecology":"","habitat_society":""}];
